css:
/* Modales (Login & Perfil B2B) */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: #FFFFFF; width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid #E2E8F0; }
.saas-modal-overlay.hidden .saas-modal-card { transform: translateY(30px); }

.close-modal-btn { position: absolute; top: 20px; right: 20px; background: transparent; border: none; font-size: 1.8rem; color: #94a3b8; cursor: pointer; transition: color 0.2s; line-height: 1; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.close-modal-btn:hover { color: #A81200; background: #fef2f2; }

/* Login Modal */
.modal-header-center { text-align: center; margin-bottom: 20px; }
.modal-logo-clean { height: 75px; margin-bottom: 15px; object-fit: contain; }
.modal-header-center h2 { font-size: 1.8rem; font-weight: 900; color: #0A2240; margin-bottom: 10px; letter-spacing: -0.5px; }
.modal-header-center p { font-size: 0.95rem; color: #64748B; line-height: 1.5; }
.secure-badge { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 25px; font-size: 0.8rem; color: #94a3b8; font-weight: 600; }
.secure-badge svg { width: 14px; height: 14px; }

/* Perfil B2B Modal */
.profile-card { max-width: 480px; padding: 0; overflow: hidden;}
.profile-header { background: #f8fafc; padding: 30px; display: flex; align-items: center; gap: 20px; border-bottom: 1px solid #E2E8F0; }
.profile-avatar-img { width: 64px; height: 64px; border-radius: 50%; object-fit: cover; box-shadow: 0 4px 10px rgba(10,34,64,0.1); border: 2px solid #FFFFFF; background: #E2E8F0;}
.profile-info h2 { font-size: 1.25rem; font-weight: 800; color: #0F172A; margin-bottom: 2px; line-height: 1.2; word-break: break-word;}
.user-email { font-size: 0.9rem; color: #64748b; font-weight: 500; }

.reorder-section { padding: 30px; }
.reorder-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.reorder-header h3 { font-size: 1.05rem; font-weight: 800; color: #0A2240; text-transform: uppercase; }

.order-list-preview { background: #f8fafc; border: 1px solid #E2E8F0; border-radius: 12px; padding: 15px 20px; margin-bottom: 25px; }
.order-list-preview ul { list-style: none; display: flex; flex-direction: column; gap: 8px; padding: 0; margin: 0; }
.order-list-preview li { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #0F172A; font-weight: 500; }
.order-list-preview li svg { width: 16px; color: #10b981; }

.logout-wrapper { padding: 0 30px 25px; display: flex; justify-content: center; }
.btn-logout { background: transparent; border: none; color: #94a3b8; font-size: 0.9rem; font-weight: 600; cursor: pointer; text-decoration: underline; transition: color 0.2s;}
.btn-logout:hover { color: #A81200; }

/* Icono Navbar Logueado Global */
.icon-btn.logged-in { border-color: #25D366 !important; background: rgba(37, 211, 102, 0.1) !important; position: relative; }
.icon-btn.logged-in::after { content: ''; position: absolute; top: 0px; right: 0px; width: 12px; height: 12px; background: #25D366; border-radius: 50%; border: 2px solid #16365C; z-index: 2;}
.nav-user-avatar { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: none; }
.icon-btn.logged-in .nav-user-avatar { display: block; }
.icon-btn.logged-in svg { display: none; }

/* Toasts Globales */
.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 3000; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast { background: rgba(10, 34, 64, 0.95); backdrop-filter: blur(10px); color: #FFFFFF; padding: 14px 28px; border-radius: 50px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; animation: toastSlideUp 0.3s ease forwards; border: 1px solid rgba(255,255,255,0.1); }
.toast svg { width: 20px; color: #25D366; }
.toast.fade-out { animation: toastFadeOut 0.4s ease forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }


/* =========================================
   1. VARIABLES Y BASE 
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-blue-light: #16365C; 
    --zarco-blue-glass: rgba(10, 34, 64, 0.95); 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --wa-green-dark: #1DA851;

    --bg-dashboard: #F4F7F9; /* Mismo fondo limpio B2B que Catálogo y Perfil */
    --border-soft: #E2E8F0;
    --text-main: #0F172A;
    --text-muted: #64748B;

    --transition-fast: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { overflow-x: hidden; scroll-behavior: smooth; width: 100%; }

body.bg-dashboard { font-family: 'Inter', sans-serif; color: var(--text-main); background-color: var(--bg-dashboard); line-height: 1.6; }

.nav-container { width: 90%; max-width: 1400px; margin: 0 auto; position: relative; }
.desktop-only { display: block; } .mobile-only { display: none; }
.text-red { color: var(--zarco-red) !important; }
.text-center { text-align: center !important; }
.w-100 { width: 100% !important; }

/* REVEAL ENGINE FLUIDO */
.reveal-up { opacity: 0; transform: translateY(30px); transition: opacity 1s var(--expo), transform 1s var(--expo); }
.reveal-up.active { opacity: 1; transform: translateY(0); }
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.8s ease, transform 0.8s ease; }
.reveal.active { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 


/* =========================================
   2. ESTRUCTURA PRINCIPAL CONTACTO
   ========================================= */
.contact-page-wrapper { padding-top: 240px; padding-bottom: 80px; position: relative;}

.contact-master-grid { display: grid; grid-template-columns: 1fr 1.3fr; gap: 80px; align-items: flex-start; margin-bottom: 80px; max-width: 1250px; margin-left: auto; margin-right: auto;}

/* COLUMNA IZQUIERDA: INFO */
.contact-info-side { display: flex; flex-direction: column; }
.heritage-badge.minimal-badge { display: inline-block; background: rgba(10, 34, 64, 0.05); color: var(--zarco-blue); font-size: 0.75rem; font-weight: 900; letter-spacing: 2px; padding: 8px 16px; border-radius: 50px; text-transform: uppercase; margin-bottom: 25px; align-self: flex-start; border: 1px solid rgba(10,34,64,0.1); }
.contact-main-title { font-size: 4rem; font-weight: 900; line-height: 1.1; color: var(--zarco-blue); margin-bottom: 20px; letter-spacing: -1.5px; }
.contact-main-desc { font-size: 1.15rem; color: var(--text-muted); line-height: 1.6; margin-bottom: 50px; max-width: 500px; font-weight: 400; }

/* Lista de Datos */
.contact-data-list { display: flex; flex-direction: column; gap: 35px; }
.data-item { display: flex; align-items: flex-start; gap: 20px; transition: transform 0.3s ease; }
.data-item:hover { transform: translateX(5px); }

.data-icon { width: 50px; height: 50px; border-radius: 14px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); }
.data-icon.green-icon { background: linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%); color: #16A34A; border: 1px solid #bbf7d0; }
.data-icon.blue-icon { background: linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%); color: var(--zarco-blue); border: 1px solid #cbd5e1; }
.data-icon.red-icon { background: linear-gradient(135deg, #fef2f2 0%, #ffe4e6 100%); color: var(--zarco-red); border: 1px solid #fecdd3; }
.data-icon svg { width: 24px; height: 24px; stroke-width: 2.2px; }

.data-content { display: flex; flex-direction: column; justify-content: center; min-height: 50px; }
.data-content h3 { font-size: 0.9rem; font-weight: 800; color: #94A3B8; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 4px; line-height: 1;}
.data-content a, .node-p { font-size: 1.1rem; font-weight: 600; color: var(--zarco-blue); text-decoration: none; line-height: 1.5; margin: 0; }
.data-content a:hover { color: var(--zarco-red); }
.node-p span { color: var(--text-muted); display: inline-block; width: 140px; }
.node-p strong { font-weight: 700; color: var(--text-main); }

/* COLUMNA DERECHA: FORMULARIO B2B */
.contact-form-side { display: flex; flex-direction: column; }
.clean-form-card { background: var(--white); border-radius: 24px; padding: 50px; border: 1px solid var(--border-soft); box-shadow: 0 20px 50px -10px rgba(10,34,64,0.06), 0 0 0 1px rgba(0,0,0,0.02) inset; }

.form-header-minimal { margin-bottom: 40px; }
.form-header-minimal h2 { font-size: 2.2rem; font-weight: 900; color: var(--zarco-blue); margin-bottom: 10px; letter-spacing: -0.5px; }
.form-header-minimal p { font-size: 1.05rem; color: var(--text-muted); line-height: 1.5; }

.b2b-form-clean { display: flex; flex-direction: column; gap: 24px; }
.form-row-clean { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.form-group-clean { display: flex; flex-direction: column; gap: 8px; }
.form-group-clean label { font-size: 0.85rem; font-weight: 800; color: #64748B; text-transform: uppercase; letter-spacing: 1px; padding-left: 4px; }

.select-wrapper-clean { position: relative; }
.select-wrapper-clean svg { position: absolute; right: 18px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; color: #64748b; pointer-events: none; }

.input-clean { width: 100%; padding: 16px 20px; background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 12px; font-size: 1.05rem; font-family: 'Inter', sans-serif; color: var(--zarco-blue); font-weight: 500; transition: all 0.2s ease; appearance: none; box-shadow: inset 0 2px 4px rgba(0,0,0,0.01); }
.input-clean:focus { outline: none; border-color: var(--zarco-blue); background: var(--white); box-shadow: 0 0 0 4px rgba(10, 34, 64, 0.08); }
.input-clean::placeholder { color: #CBD5E1; font-weight: 400; }
textarea.input-clean { resize: vertical; min-height: 120px; }

/* BOTÓN DE WHATSAPP + TRUST BADGES */
.form-submit-wrapper { display: flex; flex-direction: column; gap: 15px; margin-top: 15px; align-items: flex-start;}
.btn-whatsapp-submit { 
    background: linear-gradient(135deg, var(--wa-green) 0%, var(--wa-green-dark) 100%);
    color: var(--white); 
    padding: 16px 36px; 
    font-size: 1.05rem; 
    font-weight: 800; 
    border-radius: 12px; 
    border: none; 
    cursor: pointer; 
    display: inline-flex; 
    align-items: center; 
    justify-content: center; 
    gap: 12px; 
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1); 
    box-shadow: 0 4px 15px rgba(37, 211, 102, 0.3), inset 0 -3px 0 rgba(0,0,0,0.1); 
    letter-spacing: 0.5px;
}
.btn-whatsapp-submit svg { width: 22px; height: 22px; fill: currentColor; transition: transform 0.3s ease;}
.btn-whatsapp-submit:hover { transform: translateY(-3px); box-shadow: 0 12px 25px rgba(37, 211, 102, 0.4), inset 0 -3px 0 rgba(0,0,0,0.1); }
.btn-whatsapp-submit:hover svg { transform: scale(1.1); }
.btn-whatsapp-submit:active { transform: translateY(1px); box-shadow: inset 0 2px 0 rgba(0,0,0,0.1); }

/* Badges de Confianza con icono fijo */
.trust-badges-row { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.trust-badge { display: flex; align-items: center; gap: 6px; font-size: 0.85rem; color: var(--text-muted); font-weight: 600; }
.trust-badge svg { width: 14px; height: 14px; color: #16A34A; flex-shrink: 0; }

/* =========================================
   3. MAPA INFERIOR (ESTÉTICO)
   ========================================= */
.contact-map-bottom { max-width: 1250px; margin: 0 auto; width: 100%; margin-top: 20px; }
.map-aesthetic-wrapper { position: relative; width: 100%; height: 500px; border-radius: 24px; overflow: hidden; box-shadow: 0 25px 50px -12px rgba(10,34,64,0.15); border: 1px solid var(--border-soft); background: #E2E8F0; }
.map-iframe-clean { width: 100%; height: 100%; border: none; }

.map-info-panel { position: absolute; bottom: 30px; left: 30px; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); padding: 20px 25px; border-radius: 16px; box-shadow: 0 15px 35px rgba(0,0,0,0.1); border: 1px solid rgba(255,255,255,0.8); display: flex; align-items: flex-start; gap: 15px; max-width: 400px; }
.panel-icon { width: 36px; height: 36px; background: rgba(168,18,0,0.05); color: var(--zarco-red); border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.panel-icon svg { width: 20px; height: 20px; }
.panel-text { display: flex; flex-direction: column; gap: 4px; }
.panel-text strong { color: var(--zarco-red); font-size: 0.8rem; letter-spacing: 1.5px; font-weight: 900; }
.panel-text span { color: var(--zarco-blue); font-size: 1rem; font-weight: 600; line-height: 1.4; }


/* =========================================
   4. RESPONSIVIDAD MÓVIL BLINDADA (CENTRADITO)
   ========================================= */
@media (max-width: 1024px) {
    .desktop-only { display: none !important; }
    .mobile-only { display: flex !important; }

    /* Layout Móvil Contacto (Ajuste Perfecto y Centrado) */
    .contact-page-wrapper { padding-top: 150px; padding-bottom: 50px; }
    .contact-master-grid { grid-template-columns: 1fr; gap: 40px; margin-bottom: 40px; padding: 0 5%;}

    /* Info Lado Izquierdo - CENTRADO MÓVIL */
    .contact-info-side { align-items: center; text-align: center; }
    .heritage-badge.minimal-badge { align-self: center; margin-bottom: 15px; }
    .contact-main-title { font-size: 2.8rem; letter-spacing: -1px; text-align: center; }
    .contact-main-desc { font-size: 1.1rem; margin-bottom: 30px; text-align: center; max-width: 100%; }

    /* Nodos Convertidos en Tarjetas Centradas */
    .contact-data-list { gap: 20px; width: 100%; }
    .data-item { flex-direction: column; align-items: center; padding: 25px 20px; border-radius: 16px; background: var(--white); border: 1px solid var(--border-soft); box-shadow: 0 4px 15px rgba(0,0,0,0.02); text-align: center;}
    .data-item:hover { transform: none; } 
    .data-icon { width: 55px; height: 55px; margin-bottom: 5px; }
    .data-icon svg { width: 28px; height: 28px; }

    .data-content { min-height: auto; align-items: center;}
    .data-content h3 { font-size: 0.9rem; }
    .data-content a, .node-p { font-size: 1.05rem; }
    .node-p span { width: auto; display: block; margin-bottom: 4px; }

    /* Formulario Móvil - Centrado de títulos y botón */
    .clean-form-card { padding: 35px 20px; border-radius: 20px; width: 100%;}
    .form-header-minimal { text-align: center; margin-bottom: 30px; }
    .form-header-minimal h2 { font-size: 1.8rem; }
    .form-row-clean { grid-template-columns: 1fr; gap: 15px; }
    .b2b-form-clean { gap: 15px; }
    .input-clean { padding: 14px 18px; font-size: 1rem; }

    /* Botón WhatsApp y Trust Badges Móvil */
    .form-submit-wrapper { flex-direction: column; align-items: center; gap: 12px; margin-top: 10px;}
    .btn-whatsapp-submit { width: 100%; padding: 18px; justify-content: center; font-size: 1rem; }
    .trust-badges-row { flex-direction: column; align-items: center; gap: 8px; text-align: center;}
    .trust-badge { font-size: 0.9rem; justify-content: center;}

    /* Mapa Móvil */
    .contact-map-bottom { padding: 0 5%; }
    .map-aesthetic-wrapper { height: 350px; border-radius: 20px; }
    .map-info-panel { bottom: 10px; left: 10px; right: 10px; max-width: none; padding: 15px; flex-direction: column; align-items: center; text-align: center; border-radius: 12px;}
    .panel-icon { display: flex; margin-bottom: 5px; } 
    .panel-text strong { font-size: 0.75rem; }
    .panel-text span { font-size: 0.95rem; }
}


  :root {
    --zarco-blue: #0A2240;
    --zarco-blue-light: #16365C;
    --zarco-blue-glass: rgba(10,34,64,0.95);
    --zarco-red: #A81200;
    --white: #FFFFFF;
    --wa-green: #10B981;
    --transition-fast: 0.3s cubic-bezier(0.16,1,0.3,1);
    --shadow-pop: 0 15px 35px -5px rgba(10,34,64,0.15),0 5px 15px rgba(0,0,0,0.05)
  }
  .desktop-only { display: block }
  .mobile-only { display: none }
  .navbar {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 2000;
    transition: transform .6s var(--transition-fast),box-shadow .6s var(--transition-fast);
    box-shadow: 0 4px 20px rgba(0,0,0,.15);
    font-family: 'Inter',sans-serif
  }
  .navbar.nav-hidden { transform: translateY(-100%) }
  .nav-container {
    width: 90%;
    max-width: 1400px;
    margin: 0 auto;
    position: relative
  }
  .nav-top {
    background-color: var(--zarco-blue-light);
    padding: 20px 0;
    transition: padding var(--transition-fast)
  }
  .top-container {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto
  }
  .nav-left { justify-self: start }
  .nav-center { justify-self: center }
  .nav-right {
    justify-self: end;
    display: flex;
    align-items: center;
    gap: 15px
  }
  .nav-logo img {
    height: 100px;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.3));
    transition: height var(--transition-fast);
    display: block
  }
  .nav-logo img:hover { transform: scale(1.03) }
  .nav-gif {
    height: 100px;
    object-fit: contain;
    border-radius: 8px;
    display: block;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.2))
  }
  .btn-primary {
    background-color: var(--zarco-red);
    color: var(--white);
    border: none;
    padding: 14px 32px;
    font-weight: 900;
    font-size: .85rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    cursor: pointer;
    border-radius: 6px;
    transition: all var(--transition-fast);
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px
  }
  .btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(168,18,0,.4);
    background-color: #ba1400
  }
  .nav-bottom {
    background-color: var(--zarco-blue);
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative
  }
  .bottom-container {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    position: static
  }
  .nav-menu {
    display: flex;
    list-style: none;
    gap: 4rem;
    margin: 0 auto;
    align-items: center;
    position: static;
    padding: 0
  }
  .nav-link {
    color: rgba(255,255,255,.85);
    text-decoration: none;
    font-weight: 700;
    font-size: .8rem;
    letter-spacing: 2.5px;
    position: relative;
    padding: 12px 0;
    transition: color var(--transition-fast);
    display: flex;
    align-items: center;
    gap: 6px;
    text-transform: uppercase
  }
  .nav-link:hover, .nav-link.active { color: var(--white) }
  .nav-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 3px;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--zarco-red);
    transition: width var(--transition-fast);
    border-radius: 2px 2px 0 0
  }
  .nav-link:hover::after, .nav-link.active::after { width: 100% }
  .nav-link svg {
    width: 14px;
    height: 14px;
    transition: transform var(--transition-fast);
    vertical-align: middle;
    margin-top: -1px
  }
  .has-dropdown { position: static }
  .dropdown-menu {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    width: 100vw;
    height: 55px;
    background-color: rgba(22,54,92,.85);
    backdrop-filter: blur(8px);
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 4rem;
    list-style: none;
    padding: 0;
    margin: 0;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-5px);
    transition: all var(--transition-fast);
    box-shadow: 0 10px 20px rgba(0,0,0,.1);
    z-index: 1999;
    border-top: 1px solid rgba(255,255,255,.05)
  }
  .has-dropdown:hover .dropdown-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0)
  }
  .has-dropdown:hover .nav-link svg { transform: rotate(180deg) }
  .dropdown-link {
    display: inline-block;
    color: rgba(255,255,255,.85);
    text-decoration: none;
    font-size: .8rem;
    font-weight: 700;
    letter-spacing: 2px;
    padding: 12px 0;
    position: relative;
    transition: color var(--transition-fast)
  }
  .dropdown-link:hover { color: var(--white) }
  .dropdown-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 2px;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--zarco-red);
    transition: width var(--transition-fast)
  }
  .dropdown-link:hover::after { width: 100% }
