/* 1. VARIABLES GLOBALES (Por si acaso el componente carga aislado) */
:root {
    --zarco-blue: #0A2240; 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --wa-green-dark: #1DA851;
    --transition-fast: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

/* 2. MOTOR DE ANIMACIÓN (REVEAL) */
.reveal-up { opacity: 0; transform: translateY(30px); transition: opacity 1s var(--expo), transform 1s var(--expo); }
.reveal-up.active { opacity: 1; transform: translateY(0); }
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.8s ease, transform 0.8s ease; }
.reveal.active { opacity: 1; transform: translateY(0); }

/* Animación propia para el botón flotante */
@keyframes floatPop {
    0% { opacity: 0; transform: translateY(30px) scale(0.8); }
    100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* 3. ESTILOS DEL FOOTER B2B PREMIUM */
.master-footer { 
    background: linear-gradient(135deg, var(--zarco-red) 0%, var(--zarco-red-dark) 100%); 
    color: var(--white); 
    padding: 80px 0 0; 
    position: relative; 
    box-shadow: 0 -10px 30px rgba(0,0,0,0.1); 
    margin-top: auto; 
    font-family: 'Inter', sans-serif;
}

.footer-container { 
    width: 90%; 
    max-width: 1300px; 
    margin: 0 auto; 
    display: grid; 
    grid-template-columns: 1.5fr 2fr 1fr; 
    gap: 50px; 
    padding-bottom: 60px; 
}

.footer-col { display: flex; flex-direction: column; }

/* Columna 1: Marca */
.footer-logo img { height: 80px; margin-bottom: 20px; filter: drop-shadow(0 4px 6px rgba(0,0,0,0.2)); display: block;}
.heritage-badge-footer { display: inline-block; align-self: flex-start; background: rgba(255, 255, 255, 0.15); border: 1px solid rgba(255, 255, 255, 0.4); padding: 6px 14px; border-radius: 20px; font-size: 0.75rem; font-weight: 800; letter-spacing: 2px; margin-bottom: 20px; color: var(--white); text-transform: uppercase; }
.footer-tagline { font-size: 0.95rem; line-height: 1.7; color: rgba(255, 255, 255, 0.85); max-width: 350px; margin-bottom: 30px; }

.footer-socials { display: flex; gap: 12px; }
.social-btn { display: flex; align-items: center; justify-content: center; width: 42px; height: 42px; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 50%; transition: all var(--transition-fast); }
.social-btn svg { width: 20px; height: 20px; fill: var(--white); transition: all var(--transition-fast); }
.social-btn:hover { background: var(--white); transform: translateY(-4px); box-shadow: 0 8px 15px rgba(0,0,0,0.2); }
.social-btn:hover svg { fill: var(--zarco-red); }

/* Columna 2: Navegación */
.footer-nav-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px; }
.footer-title { font-size: 1.05rem; font-weight: 900; letter-spacing: 2px; margin-bottom: 25px; position: relative; padding-bottom: 10px; color: var(--white); text-transform: uppercase; }
.footer-title::after { content: ''; position: absolute; bottom: 0; left: 0; width: 35px; height: 3px; background-color: var(--white); border-radius: 2px; }
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 14px; padding: 0; margin: 0;}
.footer-links li a { color: rgba(255, 255, 255, 0.75); text-decoration: none; font-size: 0.95rem; font-weight: 500; transition: all var(--transition-fast); display: inline-block;}
.footer-links li a:hover { color: var(--white); transform: translateX(6px); }

/* Columna 3: Contacto */
.contact-item { margin-bottom: 20px; }
.contact-item span { display: block; font-size: 0.75rem; font-weight: 800; color: rgba(255, 255, 255, 0.6); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 5px; }
.footer-address { font-size: 0.95rem; line-height: 1.6; color: var(--white); margin: 0; }

.contact-link { display: inline-flex; align-items: center; gap: 8px; color: var(--white); text-decoration: none; font-weight: 700; font-size: 1rem; transition: all var(--transition-fast); }
.contact-link svg { width: 18px; height: 18px; opacity: 0.8; }
.contact-link:hover { opacity: 0.8; transform: translateX(4px); }

/* Barra Inferior (Bottom Bar) */
.footer-bottom { background-color: rgba(0, 0, 0, 0.25); padding: 25px 0; border-top: 1px solid rgba(255, 255, 255, 0.05); }
.footer-bottom-container { 
    display: grid; 
    grid-template-columns: 1fr auto 1fr; 
    align-items: center; 
    width: 90%; 
    max-width: 1300px; 
    margin: 0 auto; 
}
.footer-bottom p { font-size: 0.85rem; color: rgba(255, 255, 255, 0.6); margin: 0;}

/* Legales a la izquierda para no estorbar con el WhatsApp */
.footer-bottom-left { justify-self: start; display: flex; align-items: center; gap: 15px; flex-wrap: wrap; }
.legal-links { display: flex; gap: 15px; border-left: 1px solid rgba(255, 255, 255, 0.2); padding-left: 15px; }
.legal-links a { color: rgba(255, 255, 255, 0.6); text-decoration: none; font-size: 0.85rem; transition: color 0.2s; }
.legal-links a:hover { color: var(--white); text-decoration: underline; }

/* Flouvia Branding */
.pwrby { justify-self: center; font-weight: 600; color: rgba(255, 255, 255, 0.6); display: flex; align-items: center; gap: 5px; text-decoration: none; transition: all 0.3s ease;}
.pwrby strong { font-weight: 900; color: var(--white); letter-spacing: 1px; font-size: 0.9rem;}
.pwrby:hover { opacity: 0.8; transform: translateY(-2px); }

/* 4. BOTÓN WHATSAPP FLOTANTE (SIN REVEAL, CON Z-INDEX ALTO Y ANIMACIÓN PROPIA) */
.whatsapp-float { 
    position: fixed; 
    bottom: 30px; 
    right: 30px; 
    background-color: var(--wa-green); 
    color: var(--white); 
    display: flex; 
    align-items: center; 
    gap: 10px; 
    padding: 12px 24px; 
    border-radius: 50px; 
    text-decoration: none; 
    font-weight: 800; 
    font-size: 0.9rem; 
    letter-spacing: 1px; 
    box-shadow: 0 8px 25px rgba(37, 211, 102, 0.4); 
    z-index: 9999; /* Nivel Dios */
    transition: background-color var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast); 
    font-family: 'Inter', sans-serif;
    animation: floatPop 0.8s var(--expo) forwards; /* Animación al cargar */
}
.whatsapp-float svg { width: 22px; height: 22px; fill: currentColor; }
.whatsapp-float:hover { transform: translateY(-5px); box-shadow: 0 12px 30px rgba(37, 211, 102, 0.6); background-color: #20BA56; }

/* 5. MEDIA QUERIES FOOTER & WHATSAPP MÓVIL */
@media (max-width: 1024px) {
    .master-footer { padding: 60px 0 0; }
    .footer-container { grid-template-columns: 1fr; gap: 40px; padding-bottom: 40px; }

    .brand-col { align-items: center; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 30px; }
